"""Tests of the Python ports against fixtures generated by the Kotlin code (fixtures/*.json, see ReplicationFixtureTest.kt)."""
import hashlib
import json
import os
import unittest

try:
    import numpy as np
except ImportError:  # the system python has no numpy: run these with eval/public_replication/.venv/bin/python
    raise unittest.SkipTest("numpy not installed; use eval/public_replication/.venv")

from . import chunker, fusion, kotlin_random, query_processing
from .lsh import LshConfig, LshIndex, projections

FIX = os.path.join(os.path.dirname(__file__), "fixtures")


def load(name):
    with open(os.path.join(FIX, name)) as f:
        return json.load(f)


class KotlinRandomTest(unittest.TestCase):
    def test_streams_match_kotlin(self):
        for key, v in load("kotlin_random.json").items():
            seed = int(key[4:])
            r = kotlin_random.XorWow(seed)
            self.assertEqual([r.next_int() for _ in range(8)], v["nextInt"], key)
            r = kotlin_random.XorWow(seed)
            self.assertEqual([float(np.float32(r.next_float())) for _ in range(16)], v["nextFloat"], key)


class ChunkerTest(unittest.TestCase):
    def test_matches_kotlin(self):
        for case in load("chunker.json")["cases"]:
            n = case["words"]
            text = "  ".join(f"w{i}" for i in range(1, n + 1))
            got = chunker.chunk_document(text, case["title"])
            exp = case["chunks"]
            self.assertEqual(len(got), len(exp), case["words"])
            for g, e in zip(got, exp):
                self.assertEqual((g.text, g.title, g.start, g.end, g.index), (e["text"], e["title"], e["start"], e["end"], e["index"]))

    def test_title_only_chunk_has_no_embedding(self):
        c = chunker.chunk_document("", "Only a title")
        self.assertEqual(len(c), 1)
        self.assertFalse(c[0].embed)
        self.assertEqual(chunker.chunk_document("", None), [])


class QueryProcessingTest(unittest.TestCase):
    def test_matches_kotlin(self):
        for c in load("query_processing.json")["cases"]:
            n = query_processing.normalize(c["raw"])
            self.assertEqual(n, c["normalized"], c["raw"])
            self.assertEqual(query_processing.bm25_query(n), c["bm25Query"], c["raw"])


def _cands(f):
    return [{"id": c["id"], "stable_key": c["stableKey"], "title": c["title"], "bm25": c["bm25Score"], "dense": c["denseScore"],
             "modified_at": c["modifiedAt"]} for c in f["candidates"]]


class FusionTest(unittest.TestCase):
    def setUp(self):
        self.f = load("fusion.json")
        self.cands = _cands(self.f)

    def _check(self, got, exp):
        self.assertEqual([c["id"] for c, _ in got], [e["id"] for e in exp])
        for (_, s), e in zip(got, exp):
            self.assertAlmostEqual(s, e["score"], delta=1e-9)

    def test_rrf(self):
        self._check(fusion.rank_rrf(self.cands, self.f["query"]), self.f["rrf"])

    def test_rrf_empty_query_has_no_title_channel(self):
        self._check(fusion.rank_rrf(self.cands, ""), self.f["rrf_empty_query"])

    def test_global_normalisation(self):
        self._check(fusion.rank_global(self.cands, self.f["query"], self.f["referenceTime"]), self.f["global"])

    def test_min_max_norm_neutral_when_flat(self):
        self.assertEqual(fusion.min_max_norm([2.0, 2.0]), [0.5, 0.5])
        self.assertEqual(fusion.min_max_norm([]), [])


class LshTest(unittest.TestCase):
    def test_projection_matrices_match_kotlin(self):
        for key, v in load("lsh.json").items():
            cfg = LshConfig.for_dataset_size(int(key[1:]))
            self.assertEqual((cfg.num_tables, cfg.num_hash_bits, cfg.projection_dim, cfg.search_candidates, cfg.probe_radius),
                             (v["numTables"], v["numHashBits"], v["projectionDim"], v["searchCandidates"], v["probeRadius"]), key)
            sha = hashlib.sha256(projections(cfg).astype("<f4").tobytes()).hexdigest()
            self.assertEqual(sha, v["projectionSha256"], key)

    def _check_index(self, n):
        v = load("lsh.json")[f"n{n}"]
        ids = np.arange(1, n + 1, dtype=np.int64)
        X = np.stack([kotlin_random.kotlin_unit_vector(int(i)) for i in ids])
        idx = LshIndex(ids, X)
        for t, tab in enumerate(idx.tables):
            h = hashlib.sha256()
            for key in sorted(tab):
                h.update(f"{key}:{','.join(str(int(i)) for i in tab[key])};".encode())
            self.assertEqual((len(tab), h.hexdigest()), (v["tables"][t]["buckets"], v["tables"][t]["sha256"]), f"table {t}")
        for q in v["queries"]:
            qv = kotlin_random.kotlin_unit_vector(q["seed"])
            for key, cap in (("default", 0), ("uncapped", -1)):
                got = idx.search(qv, 50, cap)
                self.assertEqual([i for i, _ in got], q[key]["ids"], f"{n} {key}")
                for (_, s), e in zip(got, q[key]["scores"]):
                    self.assertAlmostEqual(s, e, delta=2e-6)

    def test_index_and_search_match_kotlin_1200(self):
        self._check_index(1200)

    def test_index_and_search_match_kotlin_12000(self):
        self._check_index(12000)

    @unittest.skipUnless(os.environ.get("RUN_SLOW"), "set RUN_SLOW=1 (about a minute)")
    def test_index_and_search_match_kotlin_60000(self):
        self._check_index(60000)


if __name__ == "__main__":
    unittest.main()
